-- Tables detected: 4 | FK/REFERENCES mentions: 2
CREATE TABLE "authorisbn" (
    "authorID" int NOT NULL,
    "isbn" char(10) NOT NULL
);

CREATE TABLE "authors" (
    "authorID" int NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "firstName" char(20) NOT NULL,
    "lastName" char(20) NOT NULL,
    PRIMARY KEY ("authorID")
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8;

CREATE TABLE "publishers" (
    "publisherID" int NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "publisher-Name" char(100) NOT NULL,
    PRIMARY KEY ("publisherID")
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8;

CREATE TABLE "titles" (
    "isbn" char(10) NOT NULL,
    "title" varchar(500) NOT NULL,
    "editionNumber" int NOT NULL,
    "copyright" char(4) NOT NULL,
    "publisherID" int NOT NULL,
    "price" float NOT NULL,
    PRIMARY KEY ("isbn")
);
ALTER TABLE "authorisbn" ADD CONSTRAINT "authorID" FOREIGN KEY ("authorID") REFERENCES "authors" ("authorID") ON DELETE CASCADE ON UPDATE NO ACTION;
ALTER TABLE "titles" ADD CONSTRAINT "publisherID" FOREIGN KEY ("publisherID") REFERENCES "publishers" ("publisherID") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX ON "authorisbn" ("isbn");
CREATE INDEX ON "authorisbn" ("authorID");
CREATE INDEX ON "titles" ("publisherID");
COMMENT ON COLUMN "authorisbn"."authorID" IS 'The integer ID in this field must appear also in the authors table';
COMMENT ON COLUMN "authorisbn"."isbn" IS 'the ISBN number for a book';
COMMENT ON COLUMN "authors"."firstName" IS 'Author''s first name.';
COMMENT ON COLUMN "authors"."lastName" IS 'Author''s last name';
COMMENT ON COLUMN "publishers"."publisherID" IS 'Publisher’s ID number. This autoincremented inte-ger is the table’s primary-key field.';
COMMENT ON COLUMN "publishers"."publisher-Name" IS 'The name of the publisher.';
COMMENT ON COLUMN "titles"."isbn" IS 'ISBN number of the book';
COMMENT ON COLUMN "titles"."title" IS 'Title of the book';
COMMENT ON COLUMN "titles"."editionNumber" IS 'Edition number of the book';
COMMENT ON COLUMN "titles"."copyright" IS 'Copyright year of the book';
COMMENT ON COLUMN "titles"."publisherID" IS 'Publisher’s ID number. This value corresponds to an ID number in the publishers table.';
COMMENT ON COLUMN "titles"."price" IS 'Suggested retail price of the book';
